    wire logic signed [10:0] l2n1_w5 = 11'($signed({1'b0, n1_4})) <<< 6;
    wire logic signed [10:0] l2n1_w6 = 11'($signed({1'b0, n1_5})) <<< 6;
    wire logic signed [9:0] l2n1_w7 = 10'($signed({1'b0, n1_6})) <<< 5;
    wire logic signed [9:0] l2n1_w8 = 10'($signed({1'b0, n1_7})) <<< 5;
    wire logic signed [9:0] l2n1_w9 = 10'sd311;
    wire logic signed [9:0] l2n1_w10 = 10'(l2n1_w2) - 10'(l2n1_w1);
    wire logic signed [11:0] l2n1_w11 = 12'(l2n1_w3) + 12'(l2n1_w4);
    wire logic signed [11:0] l2n1_w12 = 12'(l2n1_w5) + 12'(l2n1_w6);
    wire logic signed [9:0] l2n1_w13 = 10'(l2n1_w7) - 10'(l2n1_w8);
    wire logic signed [12:0] l2n1_w14 = 13'(l2n1_w10) - 13'(l2n1_w11);
    wire logic signed [12:0] l2n1_w15 = 13'(l2n1_w12) + 13'(l2n1_w13);
    wire logic signed [12:0] l2n1_w16 = 13'(l2n1_w14) + 13'(l2n1_w15);
    wire logic signed [12:0] l2n1_w17 = 13'(l2n1_w16) - 13'(l2n1_w9);
    wire logic signed [12:0] n2_1 = l2n1_w17;
    wire logic signed [10:0] l2n2_w1 = 11'($signed({1'b0, n1_0})) <<< 6;
    wire logic signed [9:0] l2n2_w2 = 10'($signed({1'b0, n1_1})) <<< 5;
    wire logic signed [9:0] l2n2_w3 = 10'($signed({1'b0, n1_2})) <<< 5;
    wire logic signed [10:0] l2n2_w4 = 11'($signed({1'b0, n1_3})) <<< 6;
    wire logic signed [10:0] l2n2_w5 = 11'($signed({1'b0, n1_4})) <<< 6;
    wire logic signed [10:0] l2n2_w6 = 11'($signed({1'b0, n1_5})) <<< 6;
    wire logic signed [10:0] l2n2_w7 = 11'($signed({1'b0, n1_6})) <<< 6;
    wire logic signed [10:0] l2n2_w8 = 11'($signed({1'b0, n1_7})) <<< 6;
    wire logic signed [11:0] l2n2_w9 = 12'sd1599;
    wire logic signed [11:0] l2n2_w10 = 12'(l2n2_w1) + 12'(l2n2_w2);
    wire logic signed [10:0] l2n2_w11 = 11'(l2n2_w4) - 11'(l2n2_w3);
    wire logic signed [10:0] l2n2_w12 = 11'(l2n2_w5) - 11'(l2n2_w6);
    wire logic signed [10:0] l2n2_w13 = 11'(l2n2_w8) - 11'(l2n2_w7);
    wire logic signed [12:0] l2n2_w14 = 13'(l2n2_w10) + 13'(l2n2_w11);
    wire logic signed [11:0] l2n2_w15 = 12'(l2n2_w12) + 12'(l2n2_w13);
    wire logic signed [13:0] l2n2_w16 = 14'(l2n2_w14) + 14'(l2n2_w15);
    wire logic signed [12:0] l2n2_w17 = 13'(l2n2_w16) - 13'(l2n2_w9);
    wire logic signed [12:0] n2_2 = l2n2_w17;
    // class scores and argmax, ties to the lowest class index
    wire logic signed [13:0] s0 = 14'(n2_0);
    wire logic signed [13:0] s1 = 14'(n2_1);
    wire logic signed [13:0] s2 = 14'(n2_2);
    wire logic       ge10 = s1 > s0;
    wire logic signed [13:0] m01 = ge10 ? s1 : s0;
    wire logic [1:0] c01 = ge10 ? 2'd1 : 2'd0;
    wire logic [1:0] cls = (s2 > m01) ? 2'd2 : c01;
    logic [LATENCY-1:0] vpipe;
    always_ff @(posedge clk) begin
        out_cls <= cls;
        if (rst) vpipe <= '0; else vpipe <= in_v;
    end
    assign out_v = vpipe[LATENCY-1];
endmodule
`default_nettype wire
